//go:build integration

package kafka_test

// TLS checks: the adapter must reach a broker over a verified TLS channel and
// must refuse a certificate it cannot verify. Separate from the SASL suite so a
// failure names the right layer.
//
// The broker runs with a JKS keystore generated by
// scripts/gen-kafka-tls-certs.ps1. PEM was tried first and cannot work: Kafka
// 3.9's PemParser rejects multi-line bodies and PKCS#1 keys, so there is no
// layout openssl produces that it accepts.

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"io"
	"net/netip"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/moby/moby/api/types/container"
	"github.com/moby/moby/api/types/network"
	kafkago "github.com/segmentio/kafka-go"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/wait"

	"goshop/shared/pkg/kafka"
	"goshop/shared/pkg/messaging"
)

const (
	tlsHostPort  = "19094"
	tlsTestTopic = "goshop.order.v1"
)

// tlsMaterial points at the certificates on disk. Tests skip rather than fail
// when the material is absent: a fresh clone has only ca.crt, and the generator
// needs Docker + openssl.
func tlsMaterial(t *testing.T) string {
	t.Helper()
	dir, err := filepath.Abs(filepath.Join("..", "..", "..", "..", "kafka", "tls"))
	require.NoError(t, err)
	for _, f := range []string{"ca.crt", "kafka.keystore.jks", "kafka.truststore.jks"} {
		if _, err := os.Stat(filepath.Join(dir, f)); err != nil {
			t.Skipf("%s missing; run scripts/gen-kafka-tls-certs.ps1", f)
		}
	}
	return dir
}

// tlsBroker starts a broker that only accepts TLS connections on tlsHostPort.
func tlsBroker(t *testing.T) (addr, caFile string) {
	t.Helper()
	dir := tlsMaterial(t)
	caFile = filepath.Join(dir, "ca.crt")

	ctx, cancel := context.WithTimeout(context.Background(), 4*time.Minute)
	defer cancel()

	req := testcontainers.ContainerRequest{
		Image: "apache/kafka:3.9.0",
		Env: map[string]string{
			"KAFKA_NODE_ID":                        "1",
			"KAFKA_PROCESS_ROLES":                  "broker,controller",
			"KAFKA_CONTROLLER_QUORUM_VOTERS":       "1@127.0.0.1:9093",
			"KAFKA_LISTENERS":                      "SSL://0.0.0.0:" + tlsHostPort + ",CONTROLLER://0.0.0.0:9093",
			"KAFKA_ADVERTISED_LISTENERS":           "SSL://127.0.0.1:" + tlsHostPort + ",CONTROLLER://127.0.0.1:9093",
			"KAFKA_CONTROLLER_LISTENER_NAMES":      "CONTROLLER",
			"KAFKA_LISTENER_SECURITY_PROTOCOL_MAP": "CONTROLLER:PLAINTEXT,SSL:SSL",
			"KAFKA_INTER_BROKER_LISTENER_NAME":     "SSL",
			"KAFKA_SSL_KEYSTORE_TYPE":              "JKS",
			// The image's configure script overrides _LOCATION with
			// /etc/kafka/secrets/<FILENAME> and reads passwords from credential
			// files, so both are supplied in that directory (mounted at /tmp/tls).
			"KAFKA_SSL_KEYSTORE_FILENAME":            "kafka.keystore.jks",
			"KAFKA_SSL_KEY_CREDENTIALS":              "key.creds",
			"KAFKA_SSL_KEYSTORE_CREDENTIALS":         "store.creds",
			"KAFKA_SSL_TRUSTSTORE_TYPE":              "JKS",
			"KAFKA_SSL_TRUSTSTORE_LOCATION":          "/tmp/tls/kafka.truststore.jks",
			"KAFKA_SSL_TRUSTSTORE_PASSWORD":          "changeit",
			"KAFKA_SSL_CLIENT_AUTH":                  "none",
			"KAFKA_SSL_ENABLED_PROTOCOLS":            "TLSv1.2,TLSv1.3",
			"KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR": "1",
			"KAFKA_AUTO_CREATE_TOPICS_ENABLE":        "false",
			"KAFKA_HEAP_OPTS":                        "-Xmx512m -Xms256m",
			"CLUSTER_ID":                             "goshop-tls-kafka-0000000001",
		},
		ExposedPorts: []string{tlsHostPort + "/tcp"},
		Mounts: testcontainers.Mounts(
			testcontainers.ContainerMount{
				Source:   testcontainers.GenericBindMountSource{HostPath: dir},
				Target:   "/tmp/tls",
				ReadOnly: true,
			},
			// The image's configure script rewrites the keystore location to
			// /etc/kafka/secrets/<FILENAME>, so the files must be visible there too.
			testcontainers.ContainerMount{
				Source:   testcontainers.GenericBindMountSource{HostPath: dir},
				Target:   "/etc/kafka/secrets",
				ReadOnly: true,
			},
		),
		HostConfigModifier: func(hc *container.HostConfig) {
			hc.PortBindings = network.PortMap{
				network.MustParsePort(tlsHostPort + "/tcp"): []network.PortBinding{
					{HostIP: netip.MustParseAddr("127.0.0.1"), HostPort: tlsHostPort},
				},
			}
		},
		WaitingFor: wait.ForAll(
			wait.ForLog("Kafka Server started").WithStartupTimeout(3*time.Minute),
			wait.ForListeningPort(tlsHostPort+"/tcp").WithStartupTimeout(3*time.Minute),
		),
	}

	c, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	require.NoError(t, err, "start tls kafka container")
	t.Cleanup(func() { _ = c.Terminate(context.Background()) })

	// Topics are not auto-created, so make the one the test publishes to.
	// kafka-topics.sh cannot take the SSL settings on the command line, it needs
	// a properties file. Write one inside the container.
	props := "security.protocol=SSL\n" +
		"ssl.truststore.location=/tmp/tls/kafka.truststore.jks\n" +
		"ssl.truststore.password=changeit\n"
	code, out, cerr := c.Exec(ctx, []string{"sh", "-c", "printf '%s' '" + props + "' > /tmp/tls-client.properties"})
	require.NoError(t, cerr)
	require.Zero(t, code, writeExecOutput(out))

	code, out, cerr = c.Exec(ctx, []string{"/opt/kafka/bin/kafka-topics.sh",
		"--bootstrap-server", "127.0.0.1:" + tlsHostPort,
		"--command-config", "/tmp/tls-client.properties",
		"--create", "--topic", tlsTestTopic, "--partitions", "1", "--replication-factor", "1",
	})
	require.NoError(t, cerr)
	require.Zero(t, code, "create topic: %s", writeExecOutput(out))

	return "127.0.0.1:" + tlsHostPort, caFile
}

// tlsDialer verifies the broker certificate against our own CA.
func tlsDialer(t *testing.T, caFile string) *kafkago.Dialer {
	t.Helper()
	pem, err := os.ReadFile(caFile)
	require.NoError(t, err)
	pool := x509.NewCertPool()
	require.True(t, pool.AppendCertsFromPEM(pem))
	return &kafkago.Dialer{
		Timeout: 15 * time.Second,
		TLS:     &tls.Config{RootCAs: pool, MinVersion: tls.VersionTLS12},
	}
}

// writeExecOutput drains an Exec reader into a string for error messages.
func writeExecOutput(r io.Reader) string {
	if r == nil {
		return ""
	}
	b, _ := io.ReadAll(r)
	return string(b)
}

// ---- tests ------------------------------------------------------------------

// With KAFKA_TLS_ENABLED and a CA file, publish and consume must work over TLS.
func TestIntegration_TLSPublishesAndConsumes(t *testing.T) {
	addr, caFile := tlsBroker(t)

	t.Setenv("KAFKA_TLS_ENABLED", "true")
	t.Setenv("KAFKA_TLS_CA_FILE", caFile)

	broker, err := kafka.NewKafkaBroker(addr, nopLog(t))
	require.NoError(t, err)
	t.Cleanup(func() { _ = broker.Close() })

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	received := make(chan string, 4)
	require.NoError(t, broker.SubscribeToExchange(ctx, "goshop-direct", "tls-check", []string{"order.created"},
		func(_ messaging.Header, body []byte) error {
			received <- string(body)
			return nil
		}))
	waitForGroupJoinWith(t, tlsDialer(t, caFile), addr, "goshop.tls-check")
	time.Sleep(4 * time.Second)

	require.NoError(t, broker.Publish(ctx, "order.created", map[string]any{"event_id": "tls-1"}))

	select {
	case got := <-received:
		assert.Contains(t, got, "tls-1")
	case <-time.After(20 * time.Second):
		t.Fatal("no record consumed over TLS")
	}
}

// A CA that did not sign the broker certificate must be rejected at connection
// time, not silently trusted. The generator writes such a CA next to the real
// one (ca-untrusted.crt) for exactly this check.
func TestIntegration_TLSRejectsUntrustedCA(t *testing.T) {
	addr, _ := tlsBroker(t)
	dir := tlsMaterial(t)

	foreign := filepath.Join(dir, "ca-untrusted.crt")
	if _, err := os.Stat(foreign); err != nil {
		t.Skip("ca-untrusted.crt missing; re-run scripts/gen-kafka-tls-certs.ps1")
	}

	t.Setenv("KAFKA_TLS_ENABLED", "true")
	t.Setenv("KAFKA_TLS_CA_FILE", foreign)

	broker, err := kafka.NewKafkaBroker(addr, nopLog(t))
	require.NoError(t, err)
	t.Cleanup(func() { _ = broker.Close() })

	err = broker.Publish(context.Background(), "order.created", map[string]any{"event_id": "untrusted"})
	require.Error(t, err, "a foreign CA must reject the connection")
	assert.NotContains(t, strings.ToLower(err.Error()), "success")
}
